INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE01-0001-4000-8000-000000000001', 'Hambella', 'Ethiopia', NULL, '🇪🇹', 'Natural', 'Medium', '["blueberry","raisin","milk chocolate"]', 'Blueberry, raisin, milk chocolate. Roasted in Rotterdam by Man Met Bril.', 'Hambella Station', NULL, NULL, 'Man Met Bril Koffie');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE01-0002-4000-8000-000000000002', 'Peru BIO', 'Peru', NULL, '🇵🇪', 'Washed', 'Medium', '["milk chocolate","herbal","floral","ripe mango","honey"]', 'Milk chocolate, herbal, floral, ripe mango, honey. Roasted in Rotterdam by Man Met Bril.', '505 families', NULL, NULL, 'Man Met Bril Koffie');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE01-0003-4000-8000-000000000003', 'House Blend', 'Brazil & India', 'Cerrado & Karnataka', '🇧🇷', 'Natural', 'Medium', '["dark chocolate","sweet","creamy","nutty","big body"]', 'Dark chocolate, sweet, creamy, nutty, big body. Roasted in Rotterdam by Man Met Bril.', NULL, NULL, NULL, 'Man Met Bril Koffie');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE01-0004-4000-8000-000000000004', 'Blendy Blend', 'Brazil & Ethiopia', 'Cerrado Mineiro & Hambella', '🇧🇷', 'Natural', 'Medium', '["chocolate","caramel","creamy","round mouthfeel"]', 'Chocolate, caramel, creamy, round mouthfeel. Roasted in Rotterdam by Man Met Bril.', 'Pedra Negra & Hambella Washing Station', NULL, NULL, 'Man Met Bril Koffie');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE01-0005-4000-8000-000000000005', 'Los Osos, Colombia', 'Colombia', 'Huila', '🇨🇴', 'Washed', 'Medium', '["chocolate","berry jelly","slightly spicy"]', 'Chocolate, berry jelly, slightly spicy. Roasted in Rotterdam by Man Met Bril.', 'Santa Maria Community', NULL, NULL, 'Man Met Bril Koffie');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE01-0006-4000-8000-000000000006', 'Hotel Blend', 'Ethiopia', NULL, '🇪🇹', 'Washed', 'Medium', '["chocolate","berries","caramel"]', 'Chocolate, berries, caramel. Roasted in Rotterdam by Man Met Bril.', NULL, NULL, NULL, 'Man Met Bril Koffie');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0001-4000-8000-000000000001', 'El Indio', 'Colombia', 'Planadas, Tolima', '🇨🇴', 'Natural', 'Light', '["fruity","sweet","full body"]', 'El Indio is afkomstig van ASOPEP, een coöperatie van meer dan 170 koffieproducerende families uit Planadas, Tolima. Tolima staat bekend als een van Colombia''s meest vooraanstaande koffieregio’s en levert al jarenlang koffies die worden geselecteerd voor de prestigieuze Cup of Excellence-competitie.', 'El Indio', '1500-2150 m', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0002-4000-8000-000000000002', 'Don Osman', 'Nicaragua', 'Nueva Segovia', '🇳🇮', 'Washed', 'Medium', '["chocolate","caramel","sweet","full body"]', 'Vidita Rojo is a beautiful washed coffee from Sueva Segovia in Nicaragua. The Paguaga family manages five coffee farms here, which they manage with transparency, care for quality and integrity.', 'Osman Gutiérrez Moreno', '600-1700 meters', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0004-4000-8000-000000000004', 'Zomerspecial - Project Forest', 'Colombia', 'Tolima', '🇨🇴', 'Honey', 'Light', '["sweet"]', 'Normaal gesproken kiezen we koffie op basis van wat er al is geoogst of verwerkt, maar deze keer hebben we de rollen omgedraaid. Wij stelden vooraf de gewenste smaak vast, en Shady en Elias van Forest Coffee zorgden voor de koffie.', 'Shady & Elias Bayter', '1400-1600 m', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0005-4000-8000-000000000005', 'Juver Santa Cruz', 'Peru', 'Cajamarca, Cutervo, Callayuc', '🇵🇪', 'Washed', 'Light', '["chocolate","fruity","sweet"]', 'Deze koffie combineert het vakmanschap van boer Juver Santa Cruz met de transparante werkwijze van importeur Cultivar. Op 1.850 meter hoogte produceert Juver een expressieve koffie die dankzij de zorgvuldige verwerking een fruitig karakter, gebalanceerde zoetheid en chocolade afdronk heeft gekregen.', 'Finca El Eucalipto, Juver Santa Cruz', '1850 MASL', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0006-4000-8000-000000000006', 'Papayo Paradise', 'Colombia', 'Acevedo, Huila', '🇨🇴', 'Washed', 'Light', '["floral","sweet","full body"]', 'Voor de tweede keer zijn we enorm enthousiast over deze bijzondere koffie van boerin María Belén Díaz. Haar finca Resina is een indrukwekkende boerderij met unieke variëteiten die ze zelf verwerkt, zoals deze Papayo variëteit.', 'María Belén Díaz', '1800 MASL', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0007-4000-8000-000000000007', 'Blawan Estate', 'Indonesia', 'Java, eeuwenlang bekend als “the spice island,” is het op drie na grootste eiland van Indonesië en een belangrijke regio voor koffieteelt. De meeste Arabica groeit op het Ijen Plateau, rondom de Blawan en Jampit estates, waar de combinatie van hoogte, vulkanische bodem en microklimaat zorgt voor uitzonderlijke koffie.', '🇮🇩', 'Washed', 'Light', '["full body","tropical fruit"]', 'Omringd door vulkanen en tropische bossen groeit op de Blawan Coffee Estate een rijke, volle koffie met een stroperige body en zachte aciditeit. Perfect voor liefhebbers van een wat krachtigere, maar mooi gebalanceerde kop koffie.', 'Blawan Coffee Estate', '800-1500 MASL', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0008-4000-8000-000000000008', 'El Jaguar', 'Nicaragua', 'El Jaguar', '🇳🇮', 'Natural', 'Light', '["caramel"]', 'Voor de tweede keer kopen wij koffie van Jean-Yves Duriaux zijn familieboerderij El Jaguar en afgelopen jaar is hij bij onze branderij langsgekomen om zijn assortiment te proeven met ons team. Deze bijzondere plek ligt in een nevelwoud in de bergen van de Jinotega regio in Nicaragua.', NULL, '1200-1400 MASL', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0009-4000-8000-000000000009', 'Girma Sentayehu', 'Ethiopia', 'Yirgacheffe', '🇪🇹', 'Washed', 'Light', '["citrus","berries"]', 'Ethiopische koffie wordt vaak verhandeld als community lot: bonen van tientallen tot honderden kleine boeren die samen worden verwerkt bij een centraal washing station. Deze Yirgacheffe is echter afkomstig van één enkele producent: Girma Sentayehu.', 'Girma Sentayehu', '1750 MASL', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0010-4000-8000-000000000010', 'Torra', 'Colombia', 'Cauca', '🇨🇴', 'Washed', 'Light', '["chocolate","citrus","full body","berries"]', 'Torra is een community lot uit het Valle del Cauca in Colombia, geproduceerd door de coöperatie Cafenorte. De koffiebessen van maar liefst 246 kleine producenten worden gebundeld in één blend, waardoor kwaliteit en volume consistent blijven.', 'Café Norte', '1500-1900 MASL', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0011-4000-8000-000000000011', 'Bela Vista Blend', 'Brazil & Colombia', NULL, '🇧🇷', 'Washed', 'Medium', '["chocolate","full body","creamy"]', 'De Bela Vista Blend is onze krachtigste blend en dat proef je!Deze koffie komt uit Brazilië en Colombia en smaakt rijk en romig, met subtiele tonen van toffee en pure chocolade. De oplosbaarheid van deze koffie in water gaat wat sneller, daarom leent deze koffie zich uitermate goed voor volautomaten', NULL, NULL, NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0012-4000-8000-000000000012', 'DECAF Condor', 'Colombia', 'Tolima', '🇨🇴', 'Washed', 'Light', '["full body"]', 'Als het James Hoffmann-project ons iets heeft laten zien, is het dat zorgvuldig decafeïneren uitstekende koffies kan opleveren. Daarom werken we samen met Forest Coffee.', 'Elias & Shady Bayter', '1700-1950 masl', NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0013-4000-8000-000000000013', 'Fazenda Guardabaxo', 'Brazil', 'Morgiana', '🇧🇷', 'Natural', 'Medium', '["chocolate","caramel","nutty","sweet","full body"]', 'Deze Braziliaanse koffie voeren wij nu al voor het derde jaar. Dit oogstjaar is er een deel oogst van een nabijgelegen plantage toegevoegd om een consistentere en hogere kwaliteit koffie te produceren.', NULL, NULL, NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0014-4000-8000-000000000014', 'Pacific Blend', 'Brazil & Colombia & Indonesia', NULL, '🇧🇷', 'Washed', 'Medium', '["sweet","spicy","full body"]', 'De Pacific Blend is zo samengesteld dat kruidige aroma’s en zoethout van een Indonesische koffie een spannend accent geven aan een klassieke volzoete basis van Braziliaanse en Colombiaanse bonen. Dit is een bijzondere koffie met smaaktonen die je niet vaak samen tegenkomt, maar juist dat bijzondere ', NULL, NULL, NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0015-4000-8000-000000000015', 'Organic Blend', 'Peru & Honduras', NULL, '🇵🇪', 'Washed', 'Medium', '["chocolate","caramel","sweet","creamy"]', 'De Organic Blend is een zoete blend met tonen van melkchocolade, karamel en toffee. Deze selectie bestaat uit 100% biologisch geteelde koffies uit Peru en Honduras.', NULL, NULL, NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0016-4000-8000-000000000016', 'Latin America Blend', 'Brazil & Nicaragua', 'Minas Gerais', '🇧🇷', 'Washed', 'Medium', '["chocolate","sweet","spicy","full body"]', 'De Latin America is onze zoete en kruidige blend. Voor liefhebbers van een cappuccino is onze Latin America heerlijk.', NULL, NULL, NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE02-0017-4000-8000-000000000017', 'Original Blend', 'Brazil & Ethiopia', NULL, '🇧🇷', 'Washed', 'Medium', '["chocolate","fruity","sweet"]', 'Our Original Blend brings together the best of two continents. A super sweet Brazilian coffee with chocolate tones to which we give a fresh accent with a fruity Yirgacheffe from Ethiopia.', NULL, NULL, NULL, 'Giraffe Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0001-4000-8000-000000000001', 'El Ingenio-Meraki', 'El Salvador', NULL, '🇸🇻', 'Washed', 'Light', '["dried fruit","green apple","fudge","rounded mouthfeel"]', 'Attention! This coffee has a sticker on the packaging with a brewing recipe designed exclusively for the Meraki espresso machine.', 'El Ingenio in El Salvador by the Urrutia family', NULL, NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0002-4000-8000-000000000002', 'Finca Soledad', 'Ecuador', 'Imbabura', '🇪🇨', 'Washed', 'Light', '["apricot pie","elderflower","clementine"]', 'We’re excited to introduce a new coffee from our friend Pepe Jijón — Finca Soledad. This washed Typica lot is exceptionally elegant, with a vibrant, juicy mouthfeel that keeps us coming back for another cup.', NULL, NULL, NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0003-4000-8000-000000000003', 'Pepe Jijón', 'Ecuador', 'Imbabura', '🇪🇨', 'Washed', 'Light', '["complex","clean"]', 'We’re excited to introduce a new coffee from our friend Pepe Jijón! This exceptional Sidra from Finca Soledad is one we simply couldn’t wait to share with you.', NULL, NULL, NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0004-4000-8000-000000000004', 'Shyira', 'Rwanda', NULL, '🇷🇼', 'Washed', 'Light', '["sweet orange","redcurrant","rooibos"]', 'We’re excited to share another delicious coffee from Rwanda! The Shyira coffee is named after the Shyira Coffee Washing Station, which showcases the resilience and potential of coffee farming in Nyabihu.', NULL, '1,850–2,300 m', NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0005-4000-8000-000000000005', 'Acacia Hills', 'Tanzania', NULL, '🇹🇿', 'Washed', 'Light', '["cloudberry","chamomile","cane sugar"]', 'This washed Geisha is produced by Leon and Aideen Christianakis at Acacia Hills Coffee Estate in Oldeani, Karatu, at elevations ranging from 1,750 to 1,950 meters above sea level. It is a coffee that beautifully showcases the extraordinary potential of Tanzanian specialty coffee.', 'Leon and Aideen Christianakis at Acacia Hills Coffe', '1,750–1,950 m', NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0006-4000-8000-000000000006', 'El Ingenio', 'El Salvador', NULL, '🇸🇻', 'Washed', 'Light', '["dried fruit","green apple","fudge","rounded mouthfeel"]', 'This coffee is grown at El Ingenio in El Salvador by the Urrutia family. Once picked, the coffee cherries are transported to San Antonio, the wet mill run by Enrique Urrutia.', 'El Ingenio in El Salvador by the Urrutia family', NULL, NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0007-4000-8000-000000000007', 'Rosa Dominguez', 'Peru', NULL, '🇵🇪', 'Washed', 'Light', '["red apple","clementine","fudge","rounded aftertaste"]', 'For the first time, we are proud to present a coffee from Peru as part of our selection. At Manhattan Coffee Roasters, we are constantly working to expand our range and discover new and exciting flavor experiences.', NULL, NULL, NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0008-4000-8000-000000000008', 'Kalila Kantengwa', 'Rwanda', NULL, '🇷🇼', 'Natural', 'Light', '["complex","clean"]', 'We are excited to announce the release of a very special coffee from Rwanda. This marks the first time we have curated a Rwandan coffee for our World Class category, and the experience of tasting it was tremendous!', NULL, '1650–1900 m', NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0009-4000-8000-000000000009', 'Keramo', 'Ethiopia', NULL, '🇪🇹', 'Washed', 'Light', '["bright yellow apple","fresh lime"]', 'This washed coffee is a vibrant addition to our Ethiopian lineup, alongside Natural Bombe and Decaffeinated Kebena. Grown in the Bombe mountains at elevations of up to 2,300 meters, Keramo is produced by around 1,500 smallholder farmers working in partnership with Daye Bensa.', NULL, '2,300 m', NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0010-4000-8000-000000000010', 'Bombe', 'Ethiopia', NULL, '🇪🇹', 'Natural', 'Light', '["complex","clean"]', 'We’re excited to welcome another exceptional Ethiopian coffee to our lineup. This naturally processed lot from Daye Bensa Coffee, produced by Assefa and Mulugeta Dukamo, showcases everything we love about high-elevation Sidama coffees — clarity, elegance, and vibrant fruit character.', 'Assefa and Mulugeta Dukamo', NULL, NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0011-4000-8000-000000000011', 'Sweet Valley', 'Colombia', NULL, '🇨🇴', 'Natural', 'Light', '["complex","clean"]', 'This coffee was originally discontinued, but in collaboration with CGLE we were able to help revive this coffee and redevelop the processing and production to bring it back to life, exclusively for us! For those new to this coffee, it is a naturally processed Colombia varietal coming from the Potosi', NULL, NULL, NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE03-0012-4000-8000-000000000012', 'Jose Jijón', 'Ecuador', 'Putushio', '🇪🇨', 'Washed', 'Light', '["clementine","white grape","rose"]', 'We are excited to announce the return of the incredible Mejorado from Pepe and Jose Jijon! This new batch comes from their high-altitude farm, Putushio, located at 2,222 meters above sea level.', NULL, '2,222 m', NULL, 'Manhattan Coffee Roasters');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0001-4000-8000-000000000001', 'Bryan Bautista', 'Honduras', 'La Paz', '🇭🇳', 'Anaerobic', 'Light', '["clean","sweet"]', 'Sometimes, we just feel like buying some amazing coffees that come across our paths. This is one of them.', NULL, '1,750 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0002-4000-8000-000000000002', 'Cultivares', 'Colombia', 'Pitalito, Huila', '🇨🇴', 'Anaerobic', 'Light', '["clean","sweet"]', 'Founded by 4th generation farmer Santiago Noriega only 5 years ago, this farm puts its focus on rare, exotic varieties.', NULL, NULL, NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0003-4000-8000-000000000003', 'Passeio', 'Brazil', 'Sul-de-minas', '🇧🇷', 'Natural', 'Light', '["clean","sweet"]', 'Natural-processed Yellow Catuai, Mundo Novo, Acaia from Sul-de-minas, Brazil.', NULL, NULL, NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0004-4000-8000-000000000004', 'La Villa', 'Colombia', 'Isnos, Huila', '🇨🇴', 'Washed', 'Light', '["clean","sweet"]', 'Sometimes, I just feel like buying some amazing coffees that come across my path. This is one of them.', NULL, '1950 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0005-4000-8000-000000000005', 'El Renacer', 'Colombia', NULL, '🇨🇴', 'Washed', 'Light', '["clean","sweet"]', 'My first thermal shock coffee; a temperature-based process that creates depth and intensity.', NULL, NULL, NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0006-4000-8000-000000000006', 'Kianamui', 'Kenya', 'Kirinyaga', '🇰🇪', 'Washed', 'Light', '["clean","sweet"]', 'An affordable, seasonal special to get people acquainted with the brightness Kenyan coffees have to offer.', NULL, '1,800 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0007-4000-8000-000000000007', 'Mae Chedi', 'Thailand', 'Mae Chedi, Chiang Rai', '🇹🇭', 'Anaerobic', 'Light', '["clean","sweet"]', 'This coffee is grown in a region where tea was once the dominant crop, and where coffee is now being taken seriously by a new generation of farmers. It comes from a cooperative of nineteen young farmers who are experimenting with modern processing techniques to create unique flavor profiles. Their c', NULL, '1,100 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0008-4000-8000-000000000008', 'Mooleh Manay Excelsa', 'India', 'Coorg, Karnataka', '🇮🇳', 'Anaerobic', 'Light', '["clean","sweet"]', 'The Excelsa variety is a unique and relatively unknown specie of coffee that does not belong to the Arabica family. It grows on trees rather than shrubs, has a distinct round shape and tastes different from any Arabica we’ve ever encountered!', NULL, '900-1200 M', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0009-4000-8000-000000000009', 'Fausto Romo', 'Ecuador', 'Pichincha', '🇪🇨', 'Washed', 'Light', '["clean","sweet"]', 'We added Sidra to our collection because we were curious about the variety. It’s not one you see often, and when we tasted the first samples, it immediately stood out. It wasn’t necessarily loud or flashy, but quietly beautiful. Clean, elegant, layered, and with some similarities to Gesha. After a s', NULL, NULL, NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0010-4000-8000-000000000010', 'Huila decaf', 'Colombia', 'Pitalito, Huila', '🇨🇴', 'Washed', 'Light', '["dark chocolate","red wine","pear","plums"]', 'Decaffeinated using ethyl acetate: a by-product of sugar cane production which is in abundance in Colombia.', NULL, '1,400 – 2,100 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0011-4000-8000-000000000011', 'Espana', 'El Salvador', 'Canton Quezalapa, Apaneca', '🇸🇻', 'Anaerobic', 'Light', '["clean","sweet"]', 'Sometimes, we just feel like buying some amazing coffees that come across our paths. This is one of them.', NULL, '1,400 – 1,500 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0012-4000-8000-000000000012', 'Fontana', 'Brazil', 'Socorro, São Paulo', '🇧🇷', 'Natural', 'Light', '["clean","sweet"]', 'Whenever you want a Brazilian coffee that feels like more than just another Brazilian, Fontana is the one. Creamy, comforting and just curious enough to stand out. It placed second in the 2024 regional championships and marks Ellen Fontana’s first export to Europe. With her commitment to agroforestr', NULL, NULL, NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0013-4000-8000-000000000013', 'Sironko', 'Uganda', 'Rwenzori', '🇺🇬', 'Natural', 'Light', '["clean","sweet"]', 'A combination of the renowned SL varieties, the rich Rwenzori soil, and careful monitoring by AgriEvolve brings out the full potential of Ugandan coffee.', NULL, '1,500 – 2,000 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0014-4000-8000-000000000014', 'Argote Anaerobic', 'Colombia', 'Nariño', '🇨🇴', 'Anaerobic', 'Light', '["nutmeg","elderflower","red berry","blackcurrant","darjeeling tea"]', 'After extensive fermentation classes and experiments, Juan Pablo started actively controlling his coffee’s fermentation.', NULL, '1,950 – 2,000 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0015-4000-8000-000000000015', 'Argote Juan Pablo Super Special', 'Colombia', 'Nariño', '🇨🇴', 'Anaerobic', 'Light', '["rum","strawberry","raisin","toffee","dark chocolate"]', 'This is what happens when you give an excited producer total freedom to apply his newfound knowledge of fermentation.', NULL, '1,950 – 2,000 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0016-4000-8000-000000000016', 'Ana Restrepo', 'Colombia', 'Vereda Totoró, Sevilla, Valle de Cauca', '🇨🇴', 'Washed', 'Light', '["marzipan","honey","red apples","dark chocolate"]', 'After returning to her parents’ farm to continue the family trade, Ana Restrepo decided to transform her coffee into a specialty grade experience.', NULL, '1,500 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0017-4000-8000-000000000017', 'Argote Peaberry', 'Colombia', 'Nariño', '🇨🇴', 'Washed', 'Light', '["chocolate","red apple","raspberry","darjeeling tea"]', 'This peaberry selection requires a labour-intensive process, but gives us a brighter, more explosive coffee.', NULL, '1,950 – 2,000 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0018-4000-8000-000000000018', 'Argote Lactic Anaerobic', 'Colombia', 'Nariño', '🇨🇴', 'Anaerobic', 'Light', '["nutmeg","elderflower","red berry","blackcurrant","darjeeling tea"]', 'After extensive fermentation classes and experiments, Juan Pablo started actively controlling his coffee’s fermentation.', NULL, '1,950 – 2,000 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0019-4000-8000-000000000019', 'Argote Natural', 'Colombia', 'Nariño', '🇨🇴', 'Natural', 'Light', '["rum","strawberry","raisin","toffee","dark chocolate"]', 'After an explosive interest in Colombian naturals, we produced one together with Juan Pablo Argote to diversify his flavour portfolio.', NULL, '1,950 – 2,000 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0020-4000-8000-000000000020', 'Keramo Natural', 'Ethiopia', 'Bensa, Sidama', '🇪🇹', 'Natural', 'Light', '["lavender","passion fruit","strawberry","lime","rum"]', 'This incredible Ethiopian cooperative has made a name for itself over the past years with true dedication to quality processes.', NULL, '2,400 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0021-4000-8000-000000000021', 'Bant Sawk', 'Myanmar', 'Taunggy, Southern Shan', '🇲🇲', 'Natural', 'Light', '["candied orange","strawberry","banana","spiced toffee"]', 'Fed up with oppression by opium drug lords and local authorities, this farmer group embraced specialty coffee to collectively pave their road to independence.', NULL, '1,100 – 1,600 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0022-4000-8000-000000000022', 'Churupampa', 'Peru', 'Chirinos, San Ignacio', '🇵🇪', 'Washed', 'Light', '["clean","sweet"]', 'The result of a quality-oriented, sustainable mindset where the entire community benefits from the years of effort by a passionate family.', NULL, '1,600 – 1,900 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0023-4000-8000-000000000023', 'Argote Washed', 'Colombia', 'Nariño', '🇨🇴', 'Washed', 'Light', '["chocolate","red apple","raspberry","darjeeling tea"]', 'The story about how Juan Pablo and Efrain Argote became pioneers and took the community around them into the world of specialty coffee.', NULL, '1,950 – 2,000 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffees (id, name, origin_country, origin_region, origin_flag, process, roast_level, flavor_tags, tasting_note, producer, altitude, harvest_season, roaster) VALUES ('C0FFEE04-0024-4000-8000-000000000024', 'Keramo Washed', 'Ethiopia', 'Bensa, Sidama', '🇪🇹', 'Washed', 'Light', '["jasmin","passion fruit","peach","caramel","earl grey tea"]', 'This incredible Ethiopian cooperative has made a name for itself over the past years with true dedication to quality processes.', NULL, '2,400 m.a.s.l.', NULL, 'Shokunin Coffee');
INSERT INTO coffee_shops (id, name, address, latitude, longitude, category, rating, opening_hours, roaster_info, description, tags, google_place_id) VALUES ('A1B2C3D4-1001-0000-0000-000000000001', 'Roast', 'Middellandplein 21B, 3021 BV Rotterdam', 51.91808, 4.45785, 'Coffee Shop', 4.8, '[{"day":"Monday","hours":"Closed"},{"day":"Tuesday","hours":"8:30 AM – 5:00 PM"},{"day":"Wednesday","hours":"8:30 AM – 5:00 PM"},{"day":"Thursday","hours":"8:30 AM – 5:00 PM"},{"day":"Friday","hours":"8:30 AM – 5:00 PM"},{"day":"Saturday","hours":"9:30 AM – 5:00 PM"},{"day":"Sunday","hours":"10:00 AM – 5:00 PM"}]', 'Roasts in-house on a Probat drum, rotating single-origins with a clean, classic Nordic-leaning profile.', 'An industrial-chic roastery in Scheepvaartkwartier, a benchmark for third-wave coffee in Rotterdam and one of the most photographed cafés in the city.', '["Single Origin","Work-Friendly","Outdoor Seating"]', 'ChIJEa7fflI1xEcRJFAP3WRDpWA');
